import { chapters, tests, glossary, annotations } from './content.mjs';
import { weights, frozenOutcome, toy } from './mechanism.mjs';
import { mountLive, unmountLive } from './live.mjs';

const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];
const esc = (value) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = (value, digits=3) => Number(value).toFixed(digits);
const pct = (value, digits=1) => `${number(value * 100, digits)}%`;
const badge = (text, kind='') => `<span class="badge ${kind}">${esc(text)}</span>`;
const source = (path, title) => `<a class="source-link" href="/evidence/${esc(path)}" target="_blank" rel="noopener">${esc(title || path.split('/').pop())}</a>`;
const intro = (index, title, lead) => `<div class="chapter-intro"><p class="eyebrow">FIELD NOTES / ${String(index+1).padStart(2,'0')} — ${esc(chapters[index][1])}</p><h1>${title}</h1><p class="lead">${lead}</p></div>`;
const heading = (title, note='') => `<div class="section-title"><h2>${title}</h2>${note?`<p>${note}</p>`:''}</div>`;
const pair = (run) => run.manifest.config.baseline ? 'baseline' : `${run.manifest.config.bid_a},${run.manifest.config.bid_b}`;
const runName = (run) => pair(run)==='baseline' ? 'No-ad baseline' : `Bids (${pair(run)})`;
const runSource = (run, file, title) => source(`${run.path}/${file}`,title);
const factsHTML = (scenario) => scenario.advertisers.map((ad,i)=>`<div class="panel ${i?'b':'a'}"><p class="eyebrow">ADVERTISER ${i?'B':'A'} / ALLOWED FACTS</p><h3>${esc(ad.brand)}</h3><ul class="facts">${ad.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`).join('');
const state = {chapter:0,run:1,step:39,decoderStep:3,testGroup:'all',testId:'test_cache_matches_uncached_and_suffixes_remain_identical',failureRun:1,failureTab:'claims',toyA:1,toyB:1,toyBranch:'contested',frozenA:1,frozenB:1};
let data, mainRuns, capRun, timer=null;

function label(id) { return data.token_labels[id] || `token #${id}`; }
function stopPlayback(){ if(timer){clearInterval(timer);timer=null;} }
function navigate(id){ location.hash=id; }
function render(){
  stopPlayback();
  unmountLive();
  const id=location.hash.slice(1) || 'question';
  const live=id==='live';
  state.chapter=live?-1:Math.max(0,chapters.findIndex(c=>c[0]===id));
  $('.workspace').classList.toggle('live-workspace',live);
  $('.replay-label').textContent=live?'LIVE LOCAL INFERENCE':'RECORDED EVIDENCE';
  $('#chapters').innerHTML=`<a class="live-nav" href="#live" ${live?'aria-current="page"':''}><span class="number">↗</span>Live Lab <span class="badge">LIVE</span></a><a class="live-nav atlas-nav" href="/atlas.html"><span class="number">◆</span>Atlas Explorer <span class="badge">REPLAY</span></a>`+chapters.map(([key,title],i)=>`<a href="#${key}" ${i===state.chapter?'aria-current="page"':''}><span class="number">${String(i+1).padStart(2,'0')}</span>${title}</a>`).join('');
  if(live){document.title='Live Lab · Token Auction Lab';mountLive();window.scrollTo({top:0});return;}
  $('#content').innerHTML=[question,auction,decoder,testPage,runs,failures,evidence][state.chapter]();
  $('#previous').disabled=state.chapter===0;
  $('#next').textContent=state.chapter===chapters.length-1?'Back to the question ↗':'Next chapter →';
  $('#progress').textContent=`${String(state.chapter+1).padStart(2,'0')} / 07`;
  document.title=`${chapters[state.chapter][1]} · Token Auction Lab`;
  bindChapter();
  window.scrollTo({top:0,behavior:'instant'});
  $('#content').focus({preventScroll:true});
  if(state.inspectOnOpen){$('#inspector').scrollIntoView({block:'start'});state.inspectOnOpen=false;}
}

function question(){
  return intro(0,'Can two advertisers<br>share <em>one voice?</em>','We wanted to let two advertisers influence the same generated message—and charge them through an explicit rule. The challenge is to connect every word to a probability, a bid, and an auditable decision.')+
  `<div class="hero-diagram"><div class="diagram-top"><span class="eyebrow" style="margin:0">THE IDEA, ONE TOKEN AT A TIME</span>${badge('CONCEPT DIAGRAM','synthetic')}</div><div class="diagram-flow"><div class="flow-person"><div class="flow-icon">A</div><h3>HarborHop</h3><p>“Recommend the shuttle”</p></div><div class="flow-arrow"><span>p_A + bid</span></div><div class="auction-core"><div class="tiny">ONE SHARED DECISION</div><strong>Token auction</strong><p>Mix probabilities · sample · charge</p></div><div class="flow-arrow reverse"><span>p_B + bid</span></div><div class="flow-person b"><div class="flow-icon">B</div><h3>Lantern House</h3><p>“Recommend the hotel”</p></div></div><div class="flow-output"><small>ONE SHARED MESSAGE</small>Enjoy your weekend in the Harbor District…</div><p class="diagram-caption">Exactly two bidders. One model and tokenizer. A shared sequence of selected token IDs.</p></div>
  <div class="split-summary"><div><p class="eyebrow">WHAT WORKED</p><h3>The mechanics held up.</h3><p>The original 11 auction tests and 10 prompt/decoder tests passed. Real local generation produced auditable traces.</p></div><div><p class="eyebrow">WHAT DIDN’T FOLLOW</p><h3>Correct mechanics did not ensure correct facts.</h3><p>The copy invented “free luggage storage.” Cache checks also failed before we diagnosed numerical precision.</p></div></div>
  ${heading('The problem has three layers','Each needs different evidence.')}
  <div class="grid3"><div class="panel"><p class="eyebrow">01 / MECHANISM</p><h3>Are we sampling and charging correctly?</h3><p class="small muted">The output distribution must equal the bid-weighted mixture. A winner pays a threshold; agreement is free.</p></div><div class="panel"><p class="eyebrow">02 / MODEL LOOP</p><h3>Are both contexts following the same text?</h3><p class="small muted">The same selected ID must reach both separate caches. A fast cached forward should agree with recomputing the full prefix.</p></div><div class="panel"><p class="eyebrow">03 / LANGUAGE</p><h3>Does the message actually stay grounded?</h3><p class="small muted">Coherence, factual accuracy, and useful advertising need their own evaluation. Passing math tests cannot establish them.</p></div></div>
  ${heading('The tiny fictional world')}
  <p class="muted small">The user asked for a friendly message of about 40 words, using only these facts. Both advertiser contexts received all six facts; their objectives emphasized different products.</p><div class="grid2">${factsHTML(data.facts['transit-hotel'])}</div>
  <div class="callout"><strong>How to read this notebook.</strong> Start with the three-token example, then inspect the actual model runs. “Synthetic” means an illustrative fixture. “Replay” means unedited output from the real local model. Nothing here starts a new model run.</div>
  <button class="primary" data-go="auction">Start with one token →</button><div class="source-line">The experiment’s original intent ${source('CODEX_BRIEF.md','Build brief')} ${source('SMOKE_RESULTS.md','Full results report')}</div>`;
}

function auction(){
  return intro(1,'A bid changes the <em>odds.</em>','At a fixed prefix, each advertiser context supplies probabilities for the next token. Bids weight those probabilities. The auction samples one token, then charges only when the draw uses the part where the contexts disagree.')+
  `<div class="grid2"><div class="panel"><div class="replay-head"><h3>A three-token world</h3>${badge('SYNTHETIC FIXTURE','synthetic')}</div><p class="small muted section-gap">These words illustrate the reference test’s vectors. They are not probabilities measured from Qwen.</p><div class="controls"><label class="range-label">A’s bid <output id="toy-a-value"></output><input id="toy-a" aria-label="Synthetic advertiser A bid" type="range" min="0" max="3" step="0.05" value="${state.toyA}"></label><label class="range-label b">B’s bid <output id="toy-b-value"></output><input id="toy-b" aria-label="Synthetic advertiser B bid" type="range" min="0" max="3" step="0.05" value="${state.toyB}"></label></div><div class="segmented section-gap"><button data-preset="1,0">A only</button><button data-preset="1,1">Equal bids</button><button data-preset="0,1">B only</button></div><div id="toy-probabilities"></div><p class="small muted section-gap">Only the bids change. A’s vector stays [0.6, 0.3, 0.1]; B’s stays [0.1, 0.3, 0.6]. In real generation, each bid is locked for the entire round.</p></div>
  <div class="panel"><h3>Separate agreement from disagreement</h3><p class="small muted">For each token, take the smaller of its two probabilities. Add them up: 0.1 + 0.3 + 0.1 = 0.5.</p><div class="mass-bar"><span class="common" style="width:50%">50% shared</span><span class="contested" style="width:50%">50% contested</span></div><p class="small muted">The branch is random, but independent of bids. Choose a saved illustrative draw:</p><div class="segmented"><button id="toy-contested" aria-pressed="${state.toyBranch==='contested'}">Contested draw</button><button id="toy-shared" aria-pressed="${state.toyBranch==='shared'}">Shared draw</button></div><div id="toy-outcome" aria-live="polite"></div></div></div>
  <div class="callout"><strong>Try A = 0.60, then A = 0.70, with B = 1.</strong> Keep the contested draw selected. A’s candidate takes over once A’s bid exceeds 2/3. With the same tape, increasing A’s bid crosses one threshold. It does not guarantee a better whole answer.</div>
  ${heading('The rule, without the mystery')}
  <div class="steps"><div class="step"><div><h3>Find the overlap.</h3><p>Sample from it with probability C. That shared outcome is independent of bids, so both pay zero.</p></div></div><div class="step"><div><h3>On disagreement, draw a candidate for each side.</h3><p>Remove the overlap and normalize what remains. Here A’s residual can only yield “shuttle”; B’s can only yield “courtyard.”</p></div></div><div class="step"><div><h3>Use a random threshold to select the winner.</h3><p>Draw u between 0 and 1. A wins if u &lt; a/(a+b). The winner pays the bid boundary needed to win that same draw.</p></div></div></div>
  <details><summary>Show the mixture, payment formulas, and why sampling is exact</summary><div><div class="formula">λ = a / (a + b)<br>q[t] = λ p_A[t] + (1 − λ) p_B[t]<br><br>If A wins: charge_A = b × u / (1 − u)<br>If B wins: charge_B = a × (1 − u) / u</div><p class="section-gap">The common branch contributes c[t]. The contested branch contributes λ(p_A[t] − c[t]) + (1 − λ)(p_B[t] − c[t]). Adding them gives exactly q[t]. We sample probabilities over the full vocabulary. There is no argmax or post-mixture top-k/top-p filter.</p><p>At bids (1,1) and u = 0.4, A pays 2/3, rather than 1. Shared outcomes are free. If only one bid is positive, its rival’s threshold is zero, so both payments are zero. Both bids zero is rejected and belongs to the separate no-ad path.</p><p class="small muted">For positive bids, E[charge_A] = TV × b × [log(1 + a/b) − a/(a+b)]. The positive threshold integral is our expected-payment oracle. The apparent sign reversal discussed in MECHANISM.md is not an author-confirmed paper erratum.</p>${source('MECHANISM.md','Full derivation')}</div></details>
  <div class="source-line">This interaction reuses the reference fixture and preserves its tie rule: A wins only for a strict inequality. ${source('test_auction.py','Original auction tests')}</div>`;
}

function updateToy(){
  $('#toy-a-value').textContent=number(state.toyA,2);
  $('#toy-b-value').textContent=number(state.toyB,2);
  $('#toy-contested').setAttribute('aria-pressed',String(state.toyBranch==='contested'));
  $('#toy-shared').setAttribute('aria-pressed',String(state.toyBranch==='shared'));
  try{
    const [wa,wb]=weights(state.toyA,state.toyB);
    const rows=toy.tokens.map((token,i)=>`<tr><td>${token}</td>${[toy.a[i],toy.b[i],wa*toy.a[i]+wb*toy.b[i]].map((v,j)=>`<td><div class="bar-cell"><div class="bar ${['a','b','q'][j]}"><span style="width:${v*100}%"></span></div><span>${pct(v,0)}</span></div></td>`).join('')}</tr>`).join('');
    $('#toy-probabilities').innerHTML=`<p class="small">Mixture weight: <strong class="a-color">A ${pct(wa,0)}</strong> + <strong class="b-color">B ${pct(wb,0)}</strong></p><table class="probability-table"><thead><tr><th>Token</th><th>A</th><th>B</th><th>Mixture q</th></tr></thead><tbody>${rows}</tbody></table>`;
    const event=state.toyBranch==='contested'?toy.event:{...toy.event,branch:'shared',token_id:1};
    const outcome=frozenOutcome(event,state.toyA,state.toyB);
    const threshold=state.toyB*(.4/.6);
    $('#toy-outcome').innerHTML=state.toyBranch==='contested'?`<div class="kv"><span>Frozen branch draw</span><strong>0.9 ≥ C = 0.5</strong></div><div class="kv"><span>Frozen contest draw u</span><strong>0.4</strong></div><div class="kv"><span>A’s winning boundary</span><strong>a &gt; ${number(threshold,4)}</strong></div><div class="threshold-track" style="background:linear-gradient(to right,var(--b-soft) 0%,var(--b-soft) ${threshold/3*100}%,var(--a-soft) ${threshold/3*100}%,var(--a-soft) 100%)"><span class="threshold-marker" style="left:${threshold/3*100}%"></span><span class="bid-marker" style="left:calc(${state.toyA/3*100}% - 2px)"></span></div><div class="track-labels"><span>A bid 0</span><span>3</span></div><div class="outcome"><p class="eyebrow">FROZEN DRAW / ${outcome.branch} WINS</p><h3>“${toy.tokens[outcome.token_id]}”</h3><p>A pays ${number(outcome.payment_a,4)} · B pays ${number(outcome.payment_b,4)} simulated credits.</p></div><p class="small muted section-gap">The solid marker is A’s bid. The dashed marker is the critical bid; at exact equality this tape selects B.</p>`:
    `<div class="kv"><span>Frozen branch draw</span><strong>0.1 &lt; C = 0.5</strong></div><div class="kv"><span>Common-token draw</span><strong>0.5 → “weekend”</strong></div><div class="outcome"><p class="eyebrow">SHARED BRANCH / FREE</p><h3>“weekend”</h3><p>A pays 0 · B pays 0. Changing bids cannot change this frozen shared outcome.</p></div><p class="small muted section-gap">The contest draw is unused on this branch. Shared means sampled from the overlap; it does not assign semantic ownership of the word.</p>`;
  }catch(error){$('#toy-probabilities').innerHTML=`<div class="callout warning">${esc(error.message)}</div>`;$('#toy-outcome').innerHTML='<p class="muted">There is no auction outcome for bids (0,0).</p>';}
}

function decoder(){
  const m=mainRuns[1].manifest;
  return intro(2,'Two memories.<br><em>Exactly one continuation.</em>','We load the model once, but give it two different advertiser prompts. Each context keeps its own attention state. After every auction, both receive the exact same selected token ID—even when one side did not win.')+
  `<div class="replay-head section-gap"><h3>Advance the beginning of the equal-bid run</h3>${badge('REPLAY · RECORDED IDS','replay')}</div><p class="small muted">This diagram displays saved IDs from the earlier shared-facts setup; it does not call the model. Live Lab now gives each advertiser only its own brief before the shared continuation.</p><div class="context-demo">${m.prompts.map((p,i)=>`<div class="panel ${i?'b':'a'}"><div class="context-header"><h3 class="${i?'b-color':'a-color'}">Context ${i?'B':'A'}</h3><span class="mono">${p.token_ids.length} prompt tokens</span></div><div class="prefix"><span>PRIVATE PREFIX / ${i?'B':'A'}</span>Same user task + all allowed facts<br>Objective: recommend ${i?'Lantern House':'HarborHop'}</div><p class="eyebrow">EXACT SHARED SUFFIX / TOKEN IDS</p><div class="shared-suffix" id="suffix-${i}"></div><div class="kv"><span>Attention mask length</span><strong id="mask-${i}"></strong></div><div class="kv"><span>Cache, positions, and prompt</span><strong>Separate for ${i?'B':'A'}</strong></div></div>`).join('')}</div><p class="connector-caption" id="decoder-caption"></p><div class="controls"><button class="primary" id="advance-token">Append next recorded token →</button><button id="reset-context">Reset diagram</button></div>
  ${heading('Why the cache test matters')}
  <div class="grid2"><div class="panel"><p class="eyebrow">FAST PATH</p><h3>Continue from saved attention state</h3><p class="small muted">A KV cache saves work by remembering earlier tokens. But if it belongs to the wrong prompt, uses the wrong position, or misses a selected ID, the next-token probabilities are wrong.</p></div><div class="panel"><p class="eyebrow">INDEPENDENT CHECK</p><h3>Recompute the complete prefix</h3><p class="small muted">Run the same prompt plus all generated IDs without using the saved cache. Compare its next-token logits and probabilities to the cached path. Agreement checks the implementation.</p></div></div>
  <div class="callout"><strong>Why this test was relevant:</strong> the auction can be mathematically perfect and still act on the wrong model state. Cache equivalence catches that class of error. It cannot tell us whether “free luggage storage” is true.</div>
  <details><summary>What did we check, and how often?</summary><div><p>The decoder verifies both generated suffixes after every selected token, including EOS. The live rounds compare cached and full-prefix outputs at the end. Additional numerical diagnostics checked two trajectories at steps 0, 7, 23, and the final step for both contexts. Tiny-model tests compare repeatedly during continuation.</p><p>We do not claim to recompute the whole prefix after every token in the live run. Prompts are unequal lengths, so attention-mask lengths and positions remain separate even though the generated suffix IDs match.</p>${source('token_auction_lab/decoder.py','Decoder implementation')} ${source('test_decoder.py','Tests')}</div></details>
  <details><summary>Read the exact two prompts from the validated run</summary><div>${m.prompts.map((p,i)=>`<h3>Context ${i?'B':'A'}</h3><pre>${esc(p.text)}</pre>`).join('')}${runSource(mainRuns[1],'manifest.json','Manifest, including prompt IDs and hashes')}</div></details>
  <button class="primary" data-go="tests">See what each test proves →</button>`;
}

function updateDecoder(){
  const run=mainRuns[1], events=run.events.slice(0,state.decoderStep);
  for(let i=0;i<2;i++){
    $(`#suffix-${i}`).innerHTML=events.length?events.map((e,j)=>`<span class="token-id ${j===events.length-1?'newest':''}" title="${esc(label(e.token_id))}">${e.token_id}</span>`).join(''):'<span class="small muted">No generated tokens yet</span>';
    $(`#mask-${i}`).textContent=run.manifest.prompts[i].token_ids.length+events.length;
  }
  $('#decoder-caption').textContent=events.length?`Shared visible text: “${events[events.length-1].decoded_text_so_far}”`:'The two different prompts are ready. The shared continuation is empty.';
  $('#advance-token').disabled=state.decoderStep>=8;
}

function testPage(){
  return intro(3,'Passing tests answer<br><em>specific questions.</em>','Twenty-one tests passed in the recorded check. Eleven exercise the auction math; ten exercise prompts and the model loop. Select a test to see the failure it would catch—and what it cannot establish.')+
  `<div class="metrics"><div><div class="big-stat">21 <span style="font-size:18px">/ 21</span></div><div class="stat-label">Passed in the archived run</div></div><div><div class="big-stat">11</div><div class="stat-label">Original auction tests · retained</div></div><div><div class="big-stat">10</div><div class="stat-label">Prompt and decoder tests</div></div><div><div class="big-stat">0</div><div class="stat-label">Tests proving factual copy</div></div></div>
  <div class="segmented section-gap">${[['all','All 21'],['auction','Auction · 11'],['contexts','Prompts & caches · 5'],['runner','Trace & stopping · 5']].map(([id,title])=>`<button data-test-group="${id}" aria-pressed="${state.testGroup===id}">${title}</button>`).join('')}</div><div class="test-layout"><div class="test-list" id="test-list"></div><article class="panel test-detail" id="test-detail" aria-live="polite"></article></div>
  <div class="callout warning"><strong>Different evidence, different jobs.</strong> The decoder unit tests use tiny random Qwen weights to check structure. The recorded smoke tests use real pretrained Qwen weights to check live operation. Factual quality is reviewed separately; it does not inherit a “pass” from either.</div>
  <details><summary>Show the exact captured unittest output</summary><div><p>Recorded command: <code>python -m unittest -v</code> at the project root, with the inference dependencies installed. This display is an archived result, not a test running in your browser. The current prompt tests check private briefs; the archived prompt test checked the earlier shared-facts setup.</p><pre>${esc(data.test_results)}</pre>${source('TEST_RESULTS.txt','Captured output')}</div></details>
  <div class="source-line">No failed auction test was replaced with a new target. The numerical change affected live MPS cache tolerances, with evidence explained in chapter 06. ${source('test_auction.py')} ${source('test_decoder.py')}</div>`;
}

function updateTests(){
  const visible=tests.filter(t=>state.testGroup==='all'||t.group===state.testGroup);
  if(!visible.some(t=>t.id===state.testId))state.testId=visible[0].id;
  $('#test-list').innerHTML=visible.map(t=>`<button class="test-button" data-test="${t.id}" aria-pressed="${t.id===state.testId}"><span class="check" aria-label="Passed">✓</span><span>${t.title}<small>${t.group==='auction'?'REFERENCE MATH':t.group==='contexts'?'PROMPTS & MODEL STATE':'TRACE & GENERATION CONTROL'}</small></span></button>`).join('');
  const t=tests.find(t=>t.id===state.testId);
  $('#test-detail').innerHTML=`${badge('PASSED · ARCHIVED CHECK','pass')}<h2 class="section-gap">${t.title}</h2><dl class="definition"><dt>What could go wrong?</dt><dd>${t.failure}</dd><dt>What the test actually does</dt><dd>${t.method}</dd><dt>What a pass does not mean</dt><dd>${t.limit}</dd></dl><div class="source-line"><p class="test-source">${t.source}<br>${t.id}</p>${source(t.source,'Read the test source')}</div>`;
  $$('[data-test]').forEach(b=>b.addEventListener('click',()=>{state.testId=b.dataset.test;updateTests();$('#test-detail').scrollIntoView({block:'nearest',behavior:'smooth'});}));
  $$('[data-test-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.testGroup===state.testGroup)));
}

function runs(){
  return intro(4,'The model ran.<br>Here is <em>what it said.</em>','Three fixed bid pairs and a separate no-ad baseline, all with seed 7. These are saved outputs from Qwen3-4B on this Mac. Select a run, replay its text, and click any token to inspect the decision.')+
  `<div class="run-tabs" id="run-tabs">${mainRuns.map((r,i)=>`<button data-run="${i}" aria-pressed="${i===state.run}"><strong>${['A only','Equal bids','B only','No ads'][i]}</strong><small>${i===3?'Separate baseline':`A ${r.result.bid_a} · B ${r.result.bid_b} credits / token`}</small></button>`).join('')}</div>
  <div id="run-metrics" class="metrics"></div><article class="panel"><div class="replay-head"><h3 id="run-title"></h3>${badge('REPLAY · ORIGINAL MODEL OUTPUT','replay')}</div><p class="output-text" id="replay-text"></p><div class="replay-controls"><button id="play" class="primary">▶ Replay</button><button id="rewind">↤ First</button><input id="replay-slider" type="range" min="0" aria-label="Recorded token step"><label id="step-label" for="replay-slider"></label><button id="last">Last ↦</button></div><div class="token-ribbon" id="token-ribbon" aria-label="Recorded tokens"></div><div class="legend"><span><i class="dot shared"></i>Shared branch</span><span><i class="dot a"></i>A branch</span><span><i class="dot b"></i>B branch</span><span>Branch ≠ ownership of a word</span></div><div class="ledger" id="ledger"></div><p class="small muted" style="margin:16px 0 0">Playback advances every 250 ms for inspection. That is not the measured generation rate. Text is decoded from the saved sequence without editorial repair.</p></article>
  <div id="inspector"></div>
  ${heading('Compare the completed runs','One scenario, one seed. Not a quality benchmark.')}
  <div class="table-wrap"><table class="results-table"><thead><tr><th>Run</th><th>Tokens¹</th><th>Generation</th><th>First token</th><th>A charge</th><th>B charge</th><th>Mean TV</th></tr></thead><tbody>${mainRuns.map(r=>`<tr><td>${runName(r)}</td><td>${r.result.tokens}</td><td>${number(r.result.seconds)} s</td><td>${number(r.result.time_to_first_token_seconds)} s</td><td>${number(r.result.payment_a,4)}</td><td>${number(r.result.payment_b,4)}</td><td>${r.result.mean_disagreement_mass===null?'—':number(r.result.mean_disagreement_mass,4)}</td></tr>`).join('')}</tbody></table></div><p class="small muted section-gap">¹ Counts include the invisible EOS token. Charges are simulated credits summed across tokens, so a round total may exceed a per-token bid. All four main runs stopped on EOS.</p>
  <details><summary>Timing, memory, and comparison caveats</summary><div><p>Measured on an Apple M2 Max, 96 GiB unified memory, MPS float32, with sequential context forwards. Generation includes prefill, both forwards, sampling, trace/checkpoint I/O, decoding, and synchronization. Cache checks add 0.71–0.74 seconds per advertiser round and are excluded from generation timing. The model’s disk load took 3.68 seconds separately.</p><p>The baseline uses one context and a 78-token prompt, compared with two prompts of 279 and 269 tokens. Its 2.63 seconds is not a matched-cost speed comparison.</p><p>Peak process RSS: 20.33 GB, including model loading and prior rounds. Highest sampled MPS tensor allocation: 16.73 GB after prefill. The latter is not a true GPU allocator peak and misses transient allocations inside forwards. No H100 result was measured.</p></div></details>
  <div class="panel section-gap"><div class="replay-head"><h3>The separate eight-token cap check</h3>${badge('REPLAY · INTENTIONALLY TRUNCATED','replay')}</div><p class="output-text" style="min-height:0">${esc(capRun.result.text)}</p><p class="small muted">Competing hotels · bids (1,1) · seed 7. Exactly ${capRun.result.tokens} tokens, ${number(capRun.result.seconds)} seconds, stop reason <code>length</code>. It verifies stopping at the cap, not full-message quality on the second scenario.</p>${runSource(capRun,'result.json','Cap result')} ${runSource(capRun,'manifest.json','Cap manifest')}</div>
  <div class="callout warning"><strong>Notice that both brands appear even at zero bid.</strong> In these archived runs, both prompts contain all allowed facts. Live Lab now uses private briefs. A zero bid removes that context’s mixture weight; it does not ban mentions of its product. These three samples do not establish a trend in business value.</div>
  <button class="primary" data-go="failures">Read the failures alongside the facts →</button>`;
}

function setStep(step){state.step=Math.max(0,Math.min(mainRuns[state.run].events.length-1,Number(step)));updateRun();}
function updateRun(){
  const r=mainRuns[state.run],res=r.result,e=r.events[state.step],baseline=r.manifest.config.baseline;
  $('#run-title').textContent=baseline?'No-ad baseline':`HarborHop ${res.bid_a} / Lantern House ${res.bid_b}`;
  $('#run-metrics').innerHTML=[['Generation',`${number(res.seconds)} s`],['Tokens including EOS',res.tokens],['Total A charge',number(res.payment_a,4)],['Total B charge',number(res.payment_b,4)]].map(([title,value])=>`<div><div class="big-stat">${value}</div><div class="stat-label">${title}</div></div>`).join('');
  $('#replay-text').textContent=e.decoded_text_so_far || '[No visible text]';
  $('#replay-slider').max=r.events.length-1;$('#replay-slider').value=state.step;
  $('#step-label').textContent=`${state.step+1} / ${r.events.length} tokens`;
  $('#play').textContent=timer?'Ⅱ Pause':'▶ Replay';
  $('#token-ribbon').innerHTML=r.events.map((event,i)=>`<button class="token branch-${event.branch} ${i>state.step?'future':''}" data-token-step="${i}" aria-pressed="${i===state.step}" title="Step ${i} · ID ${event.token_id} · ${event.branch} branch" aria-label="Token ${i+1}: ${esc(label(event.token_id))}; ${event.branch} branch">${esc(label(event.token_id))}</button>`).join('');
  $('#ledger').innerHTML=`<span>RECORDED TOTAL THROUGH TOKEN ${state.step+1}<br><span class="small">Simulated credits · unchanged by the inspector</span></span><span>A <strong>${number(e.cumulative_a,4)}</strong></span><span>B <strong>${number(e.cumulative_b,4)}</strong></span>`;
  $$('[data-run]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.run)===state.run)));
  $$('[data-token-step]').forEach(b=>b.addEventListener('click',()=>{stopPlayback();setStep(b.dataset.tokenStep);}));
  state.frozenA=res.bid_a;state.frozenB=res.bid_b;
  $('#inspector').innerHTML=baseline?`<div class="callout"><strong>The baseline has no auction.</strong> This token was sampled from one model context. There are no two bidder distributions, common-mass split, or threshold payments to inspect. ${runSource(r,'events.jsonl','Raw baseline events')}</div>`:inspector(r,e);
  if(!baseline){['a','b'].forEach(k=>$(`#frozen-${k}`).addEventListener('input',event=>{state[k==='a'?'frozenA':'frozenB']=Number(event.target.value);stopPlayback();$('#play').textContent='▶ Replay';updateFrozen();}));updateFrozen();}
}

function inspector(r,e){
  const shared=e.branch==='shared';
  return `<div class="inspector-grid"><div class="panel"><div class="replay-head"><h3>Token ${state.step+1}: ${esc(label(e.token_id))}</h3>${badge(`ID ${e.token_id}`)}</div><p class="small muted section-gap">Next-token probabilities at the prefix <em>before</em> this token. These are the original recorded values.</p><table class="probability-table"><thead><tr><th>Candidate</th><th>p_A</th><th>p_B</th><th>q</th></tr></thead><tbody>${e.top_tokens.map(t=>`<tr class="${t.token_id===e.token_id?'chosen':''}"><td title="Token ID ${t.token_id}">${esc(t.token||'[empty]')}${t.token_id===e.token_id?' ←':''}</td><td>${pct(t.p_a,3)}</td><td>${pct(t.p_b,3)}</td><td>${pct(t.q,3)}</td></tr>`).join('')}</tbody></table><p class="small muted section-gap">Union of the displayed top candidates; not the full distribution. Rows retain their original probabilities and are not renormalized. The actual sampler used the full 151,936-entry model output.</p>${e.top_tokens.some(t=>t.token_id===e.token_id)?'':`<p class="small muted">The selected token is outside these displayed rows. Sampling was not limited to this table.</p>`}${e.checkpoint?`<p class="small">Full-array checkpoint saved: <code>${esc(e.checkpoint)}</code>.</p>`:''}${runSource(r,'events.jsonl','Original events')} ${runSource(r,'manifest.json','Run manifest')}</div>
  <div class="panel"><h3>Why this token, and this charge?</h3><div class="mass-bar"><span class="common" style="width:${e.shared_mass*100}%">${e.shared_mass>.15?pct(e.shared_mass,0):''}</span><span class="contested" style="width:${e.disagreement_mass*100}%">${e.disagreement_mass>.15?pct(e.disagreement_mass,0):''}</span></div><p class="small muted">Shared ${pct(e.shared_mass,3)} · disagreement ${pct(e.disagreement_mass,3)}</p><div class="kv"><span>Branch draw</span><strong>${number(e.tape.branch,6)} ${shared?'&lt;':'≥'} ${number(e.shared_mass,6)}</strong></div><div class="kv"><span>Recorded branch</span><strong>${shared?'shared · free':`${e.branch} wins contest`}</strong></div>${shared?`<p class="small muted section-gap">The branch draw lands in the common mass. The token is selected from normalized overlap using token draw ${number(e.tape.token_a,6)}. Both bids are irrelevant to this saved outcome.</p>`:`<div class="kv"><span>A residual candidate</span><strong>${esc(label(e.candidate_a))} <small>#${e.candidate_a}</small></strong></div><div class="kv"><span>B residual candidate</span><strong>${esc(label(e.candidate_b))} <small>#${e.candidate_b}</small></strong></div><div class="kv"><span>Contest draw / A weight</span><strong>${number(e.tape.contest,6)} / ${number(e.bid_a/(e.bid_a+e.bid_b),6)}</strong></div><p class="small section-gap">${e.branch} pays ${e.branch==='A'?`${e.bid_b} × ${number(e.tape.contest,6)} / (1 − ${number(e.tape.contest,6)})`:`${e.bid_a} × (1 − ${number(e.tape.contest,6)}) / ${number(e.tape.contest,6)}`} = <strong>${number(e.payment_a+e.payment_b,6)}</strong> credits.</p>`}
  <div class="frozen"><p class="eyebrow">LOCAL COUNTERFACTUAL / ONE TOKEN ONLY</p><h3>Change the bids. Freeze everything else.</h3><p class="muted">Same prefix, distributions, candidates, and random tape. This previews one alternative token; it does not regenerate the answer or alter recorded charges.</p><div class="controls"><label class="range-label">A bid <output id="frozen-a-value"></output><input id="frozen-a" aria-label="Counterfactual advertiser A bid" type="range" min="0" max="3" step="0.05" value="${r.result.bid_a}"></label><label class="range-label b">B bid <output id="frozen-b-value"></output><input id="frozen-b" aria-label="Counterfactual advertiser B bid" type="range" min="0" max="3" step="0.05" value="${r.result.bid_b}"></label></div><div id="frozen-output" aria-live="polite"></div></div>
  <details><summary>Read the complete saved random tape</summary><div><pre>${esc(JSON.stringify(e.tape,null,2))}</pre><p>The residual candidates were already sampled from the full distributions using token_a and token_b. They stay fixed when bids change; the inspector does not resample from the displayed table.</p></div></details></div></div>`;
}

function updateFrozen(){
  const e=mainRuns[state.run].events[state.step];
  $('#frozen-a-value').textContent=number(state.frozenA,2);$('#frozen-b-value').textContent=number(state.frozenB,2);
  try{
    const o=frozenOutcome(e,state.frozenA,state.frozenB);
    $('#frozen-output').innerHTML=`<div class="outcome"><p class="eyebrow">${o.branch==='shared'?'STILL SHARED':`${o.branch} WINS`} / PREVIEW ONLY</p><h3>${esc(label(o.token_id))}</h3><p>A ${number(o.payment_a,6)} · B ${number(o.payment_b,6)} credits</p></div>${e.branch!=='shared'?`<p class="small muted" style="margin:12px 0 0">At this B bid, A wins above ${number(state.frozenB*(e.tape.contest/(1-e.tape.contest)),6)}. At equality, B wins. Token #${o.token_id} ${o.token_id===e.token_id?'matches':'differs from'} the recorded choice.</p>`:''}`;
  }catch(error){$('#frozen-output').innerHTML=`<div class="callout warning">${esc(error.message)}</div>`;}
}

function highlighted(text,notes){
  const matches=notes.map(n=>({...n,start:text.indexOf(n.phrase)})).filter(n=>n.start>=0).sort((a,b)=>a.start-b.start);
  let end=0,out='';for(const n of matches){out+=esc(text.slice(end,n.start))+`<mark class="${n.level}" title="${esc(n.title)}">${esc(n.phrase)}</mark>`;end=n.start+n.phrase.length;}return out+esc(text.slice(end));
}

function freeDecision(run){
  if(pair(run)!=='1,1')return '';
  const event=run.events.find(e=>e.token_id===1910);
  const row=event.top_tokens.find(t=>t.token_id===1910);
  return `<div class="callout"><strong>Follow “free” back to the auction.</strong> At this exact prefix, A’s context assigned it ${pct(row.p_a,2)} probability; B’s assigned ${pct(row.p_b,2)}. The recorded contested draw selected B’s candidate and charged ${number(event.payment_b,6)} credits. This locates a decision in the trace; it does not assign ownership of the whole claim.<br><button id="inspect-free" style="margin-top:14px">Inspect the “free” token →</button></div>`;
}

function failures(){
  return intro(5,'Keep the failures<br><em>in the picture.</em>','There were two kinds of failure: numerical disagreement in the model loop, and unsupported claims in the language. We investigated the first and preserved the second. Neither is hidden behind the passing tests.')+
  `<div class="segmented"><button data-failure-tab="claims" aria-pressed="${state.failureTab==='claims'}">Hallucinations in the copy</button><button data-failure-tab="numerics" aria-pressed="${state.failureTab==='numerics'}">Failed cache checks</button></div><div id="failure-body"></div>`;
}

function updateFailures(){
  $$('[data-failure-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.failureTab===state.failureTab)));
  if(state.failureTab==='numerics'){$('#failure-body').innerHTML=numericalFailures();return;}
  const r=mainRuns[state.failureRun],notes=annotations[pair(r)];
  $('#failure-body').innerHTML=`<div class="run-tabs">${mainRuns.map((run,i)=>`<button data-claim-run="${i}" aria-pressed="${state.failureRun===i}"><strong>${['A only','Equal bids','B only','No ads'][i]}</strong><small>${runName(run)}</small></button>`).join('')}</div><div class="panel"><div class="replay-head"><h3>The original message, annotated</h3>${badge('REPLAY · NO TEXT REPAIR','replay')}</div><p class="output-text">${highlighted(r.result.text,notes)}</p><p class="small muted">Highlighting is an annotation layer. Every word is preserved from the saved result. Red marks identify clear invented facts; amber marks identify broader unsupported implications.</p>${runSource(r,'result.json','Unedited result')}</div>${freeDecision(r)}<div class="grid2 section-gap"><div class="panel"><p class="eyebrow">FACT CHECK / MANUAL REVIEW</p>${notes.map(n=>`<div class="claim">${badge(n.level==='definite'?'CLEAR UNSUPPORTED FACT':'UNSUPPORTED IMPLICATION',n.level==='definite'?'fail':'synthetic')}<h3>“${esc(n.phrase)}”</h3><p><strong>${n.title}.</strong> ${n.text}</p></div>`).join('')}<p class="small muted section-gap">These are specific findings from a small manual review, not an exhaustive factuality score or an automated judge.</p></div><div class="panel"><p class="eyebrow">WHAT THE MODEL WAS ALLOWED TO SAY</p>${state.failureRun===3?`<h3>The baseline had no product fact sheets.</h3><p class="small muted">Its shorter prompt asked for a concise, friendly visit suggestion without advertisements or invented local facts. It is a comparison output, not a source of factual truth.</p><pre>${esc(r.manifest.prompts[0].text)}</pre>`:data.facts['transit-hotel'].advertisers.map(ad=>`<h3>${esc(ad.brand)}</h3><ul class="facts" style="margin-bottom:18px">${ad.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`).join('')}${runSource(r,'manifest.json','Exact instructions sent to the model')}</div></div>
  <div class="callout warning"><strong>The auction has no fact checker.</strong> It mixes the distributions it receives. If those distributions support invented claims, correct sampling can still produce them. Rewriting with another model would break the link between the auctioned tokens and the shown text.</div>
  <div class="panel"><h3>What would make the quality claim stronger?</h3><p class="small muted">Run the planned two scenarios × five bid ratios × ten seeds. Score unsupported claims, brand accuracy, coherence, and payments; preserve every output. Test prompt changes separately against the original examples. A better prompt or a rejection/refund policy would need its own measured evaluation.</p></div><div class="source-line">These observations are preserved in the original report. ${source('SMOKE_RESULTS.md','Results and limitations')}</div>`;
  $$('[data-claim-run]').forEach(b=>b.addEventListener('click',()=>{state.failureRun=Number(b.dataset.claimRun);updateFailures();}));
  if($('#inspect-free'))$('#inspect-free').addEventListener('click',()=>{state.run=1;state.step=mainRuns[1].events.findIndex(e=>e.token_id===1910);state.inspectOnOpen=true;navigate('runs');});
}

function numericalFailures(){
  const diag=data.diagnostics, maxLogit=Math.max(...diag.map(d=>d.max_abs_logit_error)),maxTV=Math.max(...diag.map(d=>d.probability_tv));
  const failedRuns=data.runs.filter(r=>r.group.includes('failed'));
  return `<div class="failure-timeline"><div>${badge('ATTEMPT 1 · FAILED','fail')}<h3>MPS float16</h3><p>One round completed. The equal-bid round then failed the cache comparison.</p><span class="mono">54 / 151,936 logits outside tolerance<br>Reported mismatching error: 0.105957</span><p class="muted">Initial tolerance: atol 0.08, rtol 0.02. MPS now defaults to float32.</p>${source('smoke_results/mps-2026-10-13/float16-failed/run.log','Failure log')}</div><div>${badge('ATTEMPT 2 · FAILED','fail')}<h3>Strict float32</h3><p>The first round also failed under the initial stricter absolute tolerance.</p><span class="mono">109 / 151,936 logits outside tolerance<br>Reported mismatching error: 0.000153691</span><p class="muted">Initial tolerance: atol 0.0001, rtol 0.0001.</p>${source('smoke_results/mps-2026-10-13/float32-strict-failed/run.log','Failure log')}</div><div>${badge('DIAGNOSED · RECHECKED','pass')}<h3>Two checks together</h3><p>The final float32 sweep passed both a logit comparison and a separate bound on probability drift.</p><span class="mono">atol 0.0003, rtol 0.0001<br>Probability TV ≤ 0.0001</span><p class="muted">Original auction tests and tight tiny-model cache checks were retained.</p>${source('smoke_results/mps-2026-10-13/validated/audit.txt','Validated trace audit')}</div></div>
  ${heading('Why change a tolerance?','The numerical reason matters.')}
  <div class="grid2"><div class="panel"><h3>Measure the effect on sampling.</h3><p class="small muted">An independent diagnostic compared full-prefix and cached results on two saved trajectories, at four checkpoints, in both contexts: ${diag.length} comparisons.</p><div class="diagnostic-bars"><div><label>Largest measured logit error: <strong>${number(maxLogit,9)}</strong></label><div class="bar a"><span style="width:${maxLogit/.0003*100}%"></span></div><p class="small muted">Shown relative to the new 0.0003 absolute allowance. The actual logit check also includes a relative term.</p></div><div><label>Largest measured probability TV: <strong>${number(maxTV,10)}</strong></label><div class="bar a"><span style="width:${maxTV/.0001*100}%"></span></div><p class="small muted">${pct(maxTV/.0001,1)} of the independent 0.0001 TV limit.</p></div></div></div><div class="panel"><h3>Small score differences can mean tiny probability differences.</h3><p class="small muted">Near a zero logit, relative tolerance contributes almost nothing. A small absolute score discrepancy can trip a strict logit check while barely moving the distribution used for sampling.</p><p class="small muted">Different matrix shapes and floating-point accumulation order are the likely cause. This is an empirical diagnosis, not proof about every possible prefix or hardware backend.</p><div class="formula" style="font-size:12px">|cached − full| ≤ atol + rtol × |full|<br><br>Separately:<br>TV(p_cached, p_full) ≤ 0.0001</div></div></div>
  <div class="callout"><strong>A second guard made the change reviewable.</strong> We added a test that corrupts one logit and requires the probability-TV guard to fail even when the logit tolerance is deliberately loose. The existing tiny-model tolerance remains atol 0.00002, rtol 0.0001. No original auction target changed.</div>
  <details><summary>Inspect all 16 diagnostic comparisons</summary><div class="table-wrap"><table class="results-table"><thead><tr><th>Trajectory</th><th>Step</th><th>Context</th><th>Max logit error</th><th>Probability TV</th></tr></thead><tbody>${diag.map(d=>`<tr><td>${d.trace.includes('a1-b0')?'A only':'Equal bids'}</td><td>${d.step}</td><td>${d.bidder===0?'A':'B'}</td><td>${number(d.max_abs_logit_error,9)}</td><td>${number(d.probability_tv,10)}</td></tr>`).join('')}</tbody></table>${source('smoke_results/mps-2026-10-13/float32-strict-failed/cache-diagnostic.jsonl','Raw diagnostic JSONL')}</div></details>
  ${heading('The failed attempts are still here')}
  <p class="small muted">A cache check happens after generation. Text in an unfinished run may therefore look complete, but it has no successfully finalized result. These attempts were not substituted for the validated sweep.</p>${failedRuns.map(r=>`<details><summary>${r.manifest.dtype} · ${runName(r)} · ${r.result?'completed round in failed sweep':'cache check failed; no finalized result'}</summary><div><p class="eyebrow">REPLAY / ${r.events.length} RECORDED TOKEN EVENTS</p><p class="output-text" style="min-height:0;font-size:21px">${esc(r.result?r.result.text:r.events[r.events.length-1].decoded_text_so_far)}</p>${runSource(r,'events.jsonl','Preserved trace')} ${runSource(r,'manifest.json','Original manifest')} ${r.result?runSource(r,'result.json','Completed round result'):''}</div></details>`).join('')}
  <div class="source-line">The report documents the failed settings, numerical rationale, and final limits together. ${source('SMOKE_RESULTS.md','Full account')}</div>`;
}

function evidence(){
  const m=mainRuns[1].manifest;
  const links=[['SMOKE_RESULTS.md','The complete experiment report','All outputs, timings, numerical failures, and limitations.'],['MECHANISM.md','The mathematical construction','Common mass, residual sampling, thresholds, and the payment integral.'],['TEST_RESULTS.txt','The captured 21-test result','The original unittest output, not a browser-generated status.'],['smoke_results/mps-2026-10-13/validated/audit.txt','The independent trace audit','Text decoding, charge bounds, exact checkpoint replay, and bid isolation.'],['smoke_results/mps-2026-10-13/index.json','Archive index','Validated, length-cap, and failed attempts, with local array locations.'],['CODEX_BRIEF.md','The original build brief','The intended milestones and evaluation plan.']];
  return intro(6,'What we know.<br>What is <em>still open.</em>','We demonstrated the two-bidder mechanism inside real local decoding. We also found why implementation correctness and factual copy need separate evidence. This notebook makes both inspectable.')+
  `<div class="panel"><div class="todo-row"><span class="badge pass">DEMONSTRATED</span><div><h3>Real shared-prefix decoding on this Mac</h3><p>Three advertiser bid pairs and a no-ad baseline; fixed prompts and bids; exact shared token IDs; saved probabilities, tape, charges, and cache checks. A separate eight-token run exercised the length cap.</p></div></div><div class="todo-row"><span class="badge pass">INSPECTABLE</span><div><h3>Recorded evidence and local counterfactuals</h3><p>This walkthrough reads the existing traces. The inspector freezes one prefix and tape. It does not perform new inference, move credits, or make a full-answer causal claim.</p></div></div><div class="todo-row"><span class="badge synthetic">NEXT</span><div><h3>A round-level credit ledger</h3><p>Reserve at most max_tokens × bid per advertiser, settle actual charges, and release unused credit. Current logs record simulated payments; the reservation/refund lifecycle remains to be built.</p></div></div><div class="todo-row"><span class="badge synthetic">NEXT</span><div><h3>A broader language-quality evaluation</h3><p>The planned sweep is two scenarios × five bid ratios × ten seeds. Measure unsupported facts, exact brands, coherence, payments, and variance. Keep every failed example alongside successful ones.</p></div></div><div class="todo-row" style="border:0"><span class="badge">UNPROVEN</span><div><h3>Truthful bidding, business utility, and other hardware</h3><p>A next-token probability preference is not a monetary valuation or a conversion metric. We have no full-answer incentive guarantee, no on-chain inference verification, and no measured H100 performance.</p></div></div></div>
  ${heading('A run is more than a seed')}
  <div class="grid2"><div class="panel"><h3>Reproduction settings</h3>${[['Model',m.model_id],['Revision',m.model_revision],['Tokenizer',m.tokenizer_class],['Seed / temperature','7 / 0.8'],['Main token cap','96'],['Device / dtype','MPS / float32'],['Sampling filters','None; full vocabulary'],['Model attention','SDPA']].map(([k,v])=>`<div class="kv"><span>${k}</span><strong style="max-width:68%;overflow-wrap:anywhere">${esc(v)}</strong></div>`).join('')}<p class="small muted section-gap">Model and tokenizer use the same pinned revision. The model has 151,936 output entries; the tokenizer reports 151,669 vocabulary entries. No weights or secrets are committed.</p></div><div class="panel"><h3>What the manifests preserve</h3><p class="small muted">Full rendered prompts, prompt IDs and hashes, source hashes, model/tokenizer revision, package versions, seeds, temperature, EOS configuration, device, timings, and generation parameters.</p><pre>Python ${m.python}\nPyTorch ${m.dependencies.torch}\nTransformers ${m.dependencies.transformers}\nNumPy ${m.dependencies.numpy}\nTokenizers ${m.dependencies.tokenizers}</pre><p class="small muted">The stored trace replays without weights. Re-running the seed across changed hardware or libraries is not guaranteed to reproduce the same text. Full-array audits need the local checkpoint files listed in the archive index.</p>${source('uv.lock','Full dependency lock')}</div></div>
  <details><summary>Open a manifest or raw event stream for each completed run</summary><div>${[...mainRuns,capRun].map(r=>`<div style="margin-bottom:15px"><strong>${r.group==='length-cap'?'Length-cap check':runName(r)}</strong><br>${runSource(r,'manifest.json','Manifest')} ${runSource(r,'events.jsonl','Token events')} ${runSource(r,'result.json','Result')}</div>`).join('')}</div></details>
  ${heading('Follow any claim back to its source')}
  <div class="evidence-grid">${links.map(([path,title,desc])=>`<a class="evidence-card" href="/evidence/${path}" target="_blank" rel="noopener"><h3>${title} ↗</h3><p>${desc}</p><span class="file-tag">${path.split('/').pop()}</span></a>`).join('')}</div>
  <div class="callout"><strong>Where the work stands.</strong> The archived smoke-test source is commit <code>b8831a3</code> on <code>feat/decoder-foundation</code>. The runs were recorded on October 13, 2026 Pacific (October 14 UTC). No rented node was started for those tests; this local walkthrough needs neither a GPU nor downloads.</div>
  <p class="small muted">To reopen locally from the feature checkout: <code>.venv/bin/python -m token_auction_lab.walkthrough</code>. The server binds to 127.0.0.1 and only serves this interface and the listed experiment evidence.</p><button class="primary" data-go="runs">Return to the recorded runs →</button>`;
}

function bindChapter(){
  $$('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));
  if(state.chapter===1){
    ['a','b'].forEach(k=>$(`#toy-${k}`).addEventListener('input',e=>{state[k==='a'?'toyA':'toyB']=Number(e.target.value);updateToy();}));
    $$('[data-preset]').forEach(b=>b.addEventListener('click',()=>{[state.toyA,state.toyB]=b.dataset.preset.split(',').map(Number);$('#toy-a').value=state.toyA;$('#toy-b').value=state.toyB;updateToy();}));
    ['contested','shared'].forEach(branch=>$(`#toy-${branch}`).addEventListener('click',()=>{state.toyBranch=branch;updateToy();}));updateToy();
  }
  if(state.chapter===2){$('#advance-token').addEventListener('click',()=>{state.decoderStep++;updateDecoder();});$('#reset-context').addEventListener('click',()=>{state.decoderStep=0;updateDecoder();});updateDecoder();}
  if(state.chapter===3){$$('[data-test-group]').forEach(b=>b.addEventListener('click',()=>{state.testGroup=b.dataset.testGroup;updateTests();}));updateTests();}
  if(state.chapter===4){
    $$('[data-run]').forEach(b=>b.addEventListener('click',()=>{stopPlayback();state.run=Number(b.dataset.run);state.step=mainRuns[state.run].events.length-1;updateRun();}));
    $('#replay-slider').addEventListener('input',e=>{stopPlayback();setStep(e.target.value);});
    $('#rewind').addEventListener('click',()=>{stopPlayback();setStep(0);});$('#last').addEventListener('click',()=>{stopPlayback();setStep(mainRuns[state.run].events.length-1);});
    $('#play').addEventListener('click',()=>{if(timer){stopPlayback();updateRun();return;}if(state.step>=mainRuns[state.run].events.length-1)state.step=-1;timer=setInterval(()=>{state.step++;if(state.step>=mainRuns[state.run].events.length-1)stopPlayback();updateRun();},250);$('#play').textContent='Ⅱ Pause';});
    state.step=Math.min(state.step,mainRuns[state.run].events.length-1);updateRun();
  }
  if(state.chapter===5){$$('[data-failure-tab]').forEach(b=>b.addEventListener('click',()=>{state.failureTab=b.dataset.failureTab;updateFailures();}));updateFailures();}
}

$('#previous').addEventListener('click',()=>navigate(chapters[Math.max(0,state.chapter-1)][0]));
$('#next').addEventListener('click',()=>navigate(chapters[(state.chapter+1)%chapters.length][0]));
$('#glossary-body').innerHTML=glossary.map(([title,desc])=>`<div class="glossary-entry"><h3>${title}</h3><p>${desc}</p></div>`).join('');
$('#glossary-open').addEventListener('click',()=>$('#glossary').showModal());
$('#glossary-close').addEventListener('click',()=>$('#glossary').close());
const mobileGlossary=document.createElement('button');mobileGlossary.textContent='Glossary';mobileGlossary.className='text-button mobile-only';mobileGlossary.style.fontSize='10px';mobileGlossary.addEventListener('click',()=>$('#glossary').showModal());$('.topbar').append(mobileGlossary);
$('.skip').addEventListener('click',event=>{event.preventDefault();$('#content').focus();});
window.addEventListener('hashchange',()=>{if(data)render();});
window.addEventListener('pagehide',stopPlayback);

fetch('/api/evidence').then(response=>{if(!response.ok)throw new Error(`Evidence request failed (${response.status})`);return response.json();}).then(result=>{
  data=result;mainRuns=data.runs.filter(r=>r.group==='validated');
  mainRuns.sort((a,b)=>['1,0','1,1','0,1','baseline'].indexOf(pair(a))-['1,0','1,1','0,1','baseline'].indexOf(pair(b)));
  capRun=data.runs.find(r=>r.group==='length-cap');
  if(mainRuns.length!==4||!capRun)throw new Error('The expected archive is incomplete.');
  render();
}).catch(error=>{$('#content').innerHTML=`<div class="error"><h2>The evidence could not be loaded.</h2><p>${esc(error.message)}</p><p>Start this interface through <code>python -m token_auction_lab.walkthrough</code> in the feature checkout.</p><button id="retry">Try again</button></div>`;$('#retry').addEventListener('click',()=>location.reload());});
